// Differential harness (parallel): runs the reference executable and the Node
// port on the same argv, comparing stdout, stderr (PID-normalized) and exit code.
//
// Usage:
//   node /tmp/difftest.mjs cases.json        # cases.json = [["--a","bc",...], ...]
// or import { runAll } and pass an array of argv arrays.
import { spawn } from 'node:child_process';

const REF = '/workspace/dataset/test4_executable';
const PORT_ARGS = ['/output/test4.mjs'];
const CONCURRENCY = Number(process.env.DIFF_CONCURRENCY || 24);

const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(cmd, args) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '', err = '';
    child.stdout.setEncoding('utf8'); child.stderr.setEncoding('utf8');
    child.stdout.on('data', (d) => { out += d; });
    child.stderr.on('data', (d) => { err += d; });
    child.on('error', (e) => resolve({ out, err: String(e), code: -1 }));
    child.on('close', (code) => resolve({ out, err, code }));
  });
}

export async function runCase(argv) {
  const [a, b] = await Promise.all([run(REF, argv), run('node', [...PORT_ARGS, ...argv])]);
  const ok = a.out === b.out && norm(a.err) === norm(b.err) && a.code === b.code;
  return { ok, argv, ref: { out: a.out, err: norm(a.err), code: a.code },
           port: { out: b.out, err: norm(b.err), code: b.code } };
}

export async function runAll(cases, { label = '', showMax = 20 } = {}) {
  const fails = [];
  let pass = 0, next = 0;
  async function worker() {
    while (next < cases.length) {
      const i = next++;
      const r = await runCase(cases[i]);
      if (r.ok) pass++; else if (fails.length < 500) fails.push(r);
    }
  }
  await Promise.all(Array.from({ length: CONCURRENCY }, worker));
  console.log(`[${label}] pass=${pass}/${cases.length} fail=${cases.length - pass}`);
  for (const f of fails.slice(0, showMax)) {
    console.log('MISMATCH argv=' + JSON.stringify(f.argv));
    console.log('  ref : code=' + f.ref.code + ' out=' + JSON.stringify(f.ref.out) + ' err=' + JSON.stringify(f.ref.err));
    console.log('  port: code=' + f.port.code + ' out=' + JSON.stringify(f.port.out) + ' err=' + JSON.stringify(f.port.err));
  }
  return { pass, total: cases.length, fails };
}

if (process.argv[2]) {
  const { readFileSync } = await import('node:fs');
  const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
  const { fails } = await runAll(cases, { label: process.argv[2] });
  process.exit(fails.length ? 1 : 0);
}

/**
 * Node.js port of `test4.py`.
 *
 *     node test4.mjs --a <hrp> --b <witness version> --c <comma-separated bytes>
 *
 * Prints the encoded segwit address, or `None` when the reference `bech32`
 * package refuses to encode the inputs.  Failures reproduce the frozen Python
 * build's behaviour: argparse errors exit 2 with usage on stderr, and an
 * unhandled Python exception exits 1 with a traceback.
 */

import * as bech32 from './lib/bech32/index.mjs';
import { ArgumentParser } from './lib/py/argparse.mjs';
import { PythonError } from './lib/py/errors.mjs';
import { pythonInt } from './lib/py/int.mjs';
import {
  CONVERT_ARGUMENT_FRAMES,
  ENCODE_FRAMES,
  reportUnhandledException,
} from './lib/py/traceback.mjs';
import { writeStdout } from './lib/py/stdio.mjs';

const PROGRAM_NAME = 'test4_executable';

/** Runs `step`, reporting a Python exception through `frames` and exiting 1. */
function frozen(frames, step) {
  try {
    return step();
  } catch (error) {
    if (error instanceof PythonError) {
      reportUnhandledException(error, frames);
      process.exit(1);
    }
    throw error;
  }
}

function main() {
  const parser = new ArgumentParser({ prog: PROGRAM_NAME });
  parser.add_argument('--a', { typeName: 'str', required: true }); // HRP
  parser.add_argument('--b', { type: pythonInt, typeName: 'int', required: true }); // Witness version
  parser.add_argument('--c', { typeName: 'str', required: true }); // Witness program as comma-separated integers
  const args = parser.parse_args(process.argv.slice(2));

  const witprog = frozen(CONVERT_ARGUMENT_FRAMES, () =>
    args.c.split(',').map((piece) => pythonInt(piece)),
  );
  const result = frozen(ENCODE_FRAMES, () =>
    bech32.encode(args.a, args.b, witprog),
  );
  // `print(None)` writes "None".
  writeStdout(`${result === null ? 'None' : result}\n`);
}

main();
