/**
 * The Bech32 character set and Python's string-indexing semantics over it.
 *
 * `bech32_encode` looks up `CHARSET[d]` for every value it encodes, including
 * the caller-supplied witness version, so out-of-range versions surface as the
 * same `IndexError` CPython raises.
 */

import { PythonIndexError } from '../py/errors.mjs';

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

const LENGTH = BigInt(CHARSET.length);
// CPython converts an index through `Py_ssize_t` before bounds-checking it.
const SSIZE_MAX = (1n << 63n) - 1n;
const SSIZE_MIN = -(1n << 63n);

/** `CHARSET[index]` with CPython's negative indexing and error messages. */
export function charsetAt(index) {
  if (index > SSIZE_MAX || index < SSIZE_MIN) {
    throw new PythonIndexError("cannot fit 'int' into an index-sized integer");
  }
  const resolved = index < 0n ? index + LENGTH : index;
  if (resolved < 0n || resolved >= LENGTH) {
    throw new PythonIndexError('string index out of range');
  }
  return CHARSET[Number(resolved)];
}

/** `CHARSET.find(character)`: the value of a data character, or -1. */
export function charsetIndexOf(character) {
  return CHARSET.indexOf(character);
}
=== checksum
/**
 * The BCH checksum machinery behind Bech32.
 *
 * Every value is a BigInt so the arithmetic matches Python's unbounded integers:
 * a witness version outside 0..31 still flows through `bech32_polymod`, where
 * two's-complement XOR over negative values must agree bit for bit with CPython
 * before the result is rejected downstream.
 */

const GENERATOR = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

const LOW_25_BITS = 0x1ffffffn;
const FIVE_BITS = 31n;

/** `bech32_polymod`. */
export function bech32Polymod(values) {
  let checksum = 1n;
  for (const value of values) {
    const top = checksum >> 25n;
    checksum = ((checksum & LOW_25_BITS) << 5n) ^ value;
    for (let bit = 0; bit < 5; bit += 1) {
      if ((top >> BigInt(bit)) & 1n) checksum ^= GENERATOR[bit];
    }
  }
  return checksum;
}

/** `bech32_hrp_expand`: high bits of the HRP, a zero, then the low bits. */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const character of hrp) {
    const codePoint = BigInt(character.codePointAt(0));
    high.push(codePoint >> 5n);
    low.push(codePoint & FIVE_BITS);
  }
  return [...high, 0n, ...low];
}

/** `bech32_verify_checksum`. */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1n;
}

/** `bech32_create_checksum`: the six trailing data values. */
export function bech32CreateChecksum(hrp, data) {
  const values = [...bech32HrpExpand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n];
  const polymod = bech32Polymod(values) ^ 1n;
  const checksum = [];
  for (let position = 0; position < 6; position += 1) {
    checksum.push((polymod >> (5n * BigInt(5 - position))) & FIVE_BITS);
  }
  return checksum;
}
