const PROG20 = Array.from({ length: 20 }, (_, i) => (i * 7 + 3) % 256).join(',');
const cases = [];

// empty hrp, both forms
cases.push(['--a', '', '--b', '0', '--c', PROG20]);
cases.push(['--a=', '--b', '0', '--c', PROG20]);
cases.push(['--a', '', '--b', '5', '--c', PROG20]);

// every single ASCII char 0x20..0x7e as a 1-char hrp, separate-arg form
for (let cp = 0x20; cp <= 0x7e; cp++) {
  const ch = String.fromCharCode(cp);
  cases.push(['--a', ch, '--b', '0', '--c', PROG20]);
}
// same, --a=<ch> form
for (let cp = 0x20; cp <= 0x7e; cp++) {
  const ch = String.fromCharCode(cp);
  cases.push([`--a=${ch}`, '--b', '0', '--c', PROG20]);
}
// same, with witver 5 (no length constraint from v0)
for (let cp = 0x20; cp <= 0x7e; cp++) {
  const ch = String.fromCharCode(cp);
  cases.push([`--a=${ch}`, '--b', '5', '--c', PROG20]);
}
// control chars + DEL as hrp
for (const cp of [0x00, 0x01, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1b, 0x1f, 0x7f]) {
  cases.push([`--a=${String.fromCharCode(cp)}`, '--b', '0', '--c', PROG20]);
}

await runAll(cases, { label: 'hrp-ascii-single' });

